<?php
require __DIR__.'/_bootstrap.php';
$types=['stations','routes','trains','schedules','bogies','seats'];$type=(string)($_GET['type']??$_POST['type']??'stations');if(!in_array($type,$types,true))$type='stations';
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
 try{
  if($action==='deactivate'){if($type==='seats'){$q=$pdo->prepare('SELECT COUNT(*) FROM bookings WHERE seat_id=? AND status="Confirmed"');$q->execute([$id]);if((int)$q->fetchColumn()>0)throw new RuntimeException('This seat has a confirmed booking. Cancel that booking before deactivating the seat.');}$mapping=['stations'=>['stations','station_id'],'routes'=>['routes','route_id'],'trains'=>['trains','train_id'],'schedules'=>['schedules','schedule_id'],'bogies'=>['bogies','bogie_id'],'seats'=>['seats','seat_id']];[$table,$pk]=$mapping[$type];$stmt=$pdo->prepare("UPDATE $table SET is_active=0 WHERE $pk=?");$stmt->execute([$id]);flash($stmt->rowCount()?'Item deactivated.':'Item was already inactive or not found.');}
  elseif($action==='save'){
   if($type==='stations'){$name=post_string('station_name',120);$code=strtoupper(preg_replace('/[^A-Za-z0-9_-]/','',post_string('station_code',20)));$order=filter_var($_POST['station_order']??1,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>32767]]);$distance=trim((string)($_POST['distance_from_start']??''));if($name===''||$code===''||!$order||($distance!==''&&!is_numeric($distance)))throw new RuntimeException('Enter a station name, station code, valid order, and optional numeric distance.');if($id){$q=$pdo->prepare('UPDATE stations SET station_name=?,station_code=?,station_order=?,distance_from_start=? WHERE station_id=?');$q->execute([$name,$code,$order,$distance===''?null:$distance,$id]);}else{$q=$pdo->prepare('INSERT INTO stations(station_name,station_code,station_order,distance_from_start) VALUES(?,?,?,?)');$q->execute([$name,$code,$order,$distance===''?null:$distance]);}}
   elseif($type==='routes'){$name=post_string('route_name',150);$origin=(int)($_POST['origin_station_id']??0);$dest=(int)($_POST['destination_station_id']??0);$distance=trim((string)($_POST['distance_km']??''));$minutes=trim((string)($_POST['estimated_minutes']??''));if($name===''||!$origin||!$dest||$origin===$dest||($distance!==''&&!is_numeric($distance))||($minutes!==''&&!ctype_digit($minutes)))throw new RuntimeException('Complete the route details and choose two different stations.');if($id){$q=$pdo->prepare('UPDATE routes SET route_name=?,origin_station_id=?,destination_station_id=?,distance_km=?,estimated_minutes=? WHERE route_id=?');$q->execute([$name,$origin,$dest,$distance===''?null:$distance,$minutes===''?null:$minutes,$id]);}else{$q=$pdo->prepare('INSERT INTO routes(route_name,origin_station_id,destination_station_id,distance_km,estimated_minutes) VALUES(?,?,?,?,?)');$q->execute([$name,$origin,$dest,$distance===''?null:$distance,$minutes===''?null:$minutes]);}}
   elseif($type==='trains'){$name=post_string('train_name',120);$code=strtoupper(preg_replace('/[^A-Za-z0-9_-]/','',post_string('train_code',30)));if($name===''||$code==='')throw new RuntimeException('Enter a train name and a valid train code.');if($id){$q=$pdo->prepare('UPDATE trains SET train_name=?,train_code=? WHERE train_id=?');$q->execute([$name,$code,$id]);}else{$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO trains(train_name,train_code) VALUES(?,?)');$q->execute([$name,$code]);$trainId=(int)$pdo->lastInsertId();$allocations=[['B1','Teacher','Male'],['B2','Teacher','Female'],['B3','Student','Male'],['B4','Student','Female'],['B5','Staff','Male'],['B6','Staff','Female']];$addBogie=$pdo->prepare('INSERT INTO bogies(train_id,bogie_code,category,gender) VALUES(?,?,?,?)');$addSeat=$pdo->prepare('INSERT INTO seats(bogie_id,seat_number) VALUES(?,?)');foreach($allocations as [$bogieCode,$cat,$gender]){$addBogie->execute([$trainId,$bogieCode,$cat,$gender]);$bogieId=(int)$pdo->lastInsertId();for($n=1;$n<=40;$n++)$addSeat->execute([$bogieId,'S'.str_pad((string)$n,2,'0',STR_PAD_LEFT)]);}$pdo->commit();flash('Train added with the six standard bogies and 40 seats per bogie.');go('admin/manage.php',['type'=>$type]);}}
   elseif($type==='schedules'){$train=(int)($_POST['train_id']??0);$route=(int)($_POST['route_id']??0);$depart=(string)($_POST['departure_time']??'');$arrive=(string)($_POST['arrival_time']??'');$days=post_string('service_days',80);$dayParts=array_map(static fn($v)=>ucfirst(strtolower(trim($v))),explode(',',$days));$validDays=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];if(strtolower($days)!=='daily'&&(!$dayParts||array_diff($dayParts,$validDays)))throw new RuntimeException('Service days must be Daily or comma-separated Mon,Tue,Wed,Thu,Fri,Sat,Sun.');if(strtolower($days)==='daily')$days='Daily';else $days=implode(',',array_values(array_unique($dayParts)));$from=trim((string)($_POST['valid_from']??''));$until=trim((string)($_POST['valid_until']??''));if(!$train||!$route||!valid_time($depart)||!valid_time($arrive)||$days==='')throw new RuntimeException('Complete all required schedule details.');$from=$from===''?null:$from;$until=$until===''?null:$until;if($from&&$until&&$until<$from)throw new RuntimeException('Schedule end date must not be before its start date.');if($id){$q=$pdo->prepare('UPDATE schedules SET train_id=?,route_id=?,departure_time=?,arrival_time=?,service_days=?,valid_from=?,valid_until=? WHERE schedule_id=?');$q->execute([$train,$route,$depart,$arrive,$days,$from,$until,$id]);}else{$q=$pdo->prepare('INSERT INTO schedules(train_id,route_id,departure_time,arrival_time,service_days,valid_from,valid_until) VALUES(?,?,?,?,?,?,?)');$q->execute([$train,$route,$depart,$arrive,$days,$from,$until]);}}
   elseif($type==='bogies'){$train=(int)($_POST['train_id']??0);$code=strtoupper(preg_replace('/[^A-Za-z0-9_-]/','',post_string('bogie_code',10)));$cat=(string)($_POST['category']??'');$gender=(string)($_POST['gender']??'');if(!$train||$code===''||!in_array($cat,['Student','Teacher','Staff'],true)||!in_array($gender,['Male','Female'],true))throw new RuntimeException('Choose a train, bogie code, category, and gender.');if($id){$q=$pdo->prepare('UPDATE bogies SET train_id=?,bogie_code=?,category=?,gender=? WHERE bogie_id=?');$q->execute([$train,$code,$cat,$gender,$id]);}else{$pdo->prepare('INSERT INTO bogies(train_id,bogie_code,category,gender) VALUES(?,?,?,?)')->execute([$train,$code,$cat,$gender]);}}
   elseif($type==='seats'){$bogie=(int)($_POST['bogie_id']??0);$seat=strtoupper(trim((string)($_POST['seat_number']??'')));if(!preg_match('/^S?\d{1,3}$/',$seat)||!$bogie)throw new RuntimeException('Choose a bogie and enter a seat number such as S01.');$seat='S'.str_pad(ltrim($seat,'S'),2,'0',STR_PAD_LEFT);if($id){$q=$pdo->prepare('SELECT COUNT(*) FROM bookings WHERE seat_id=? AND status="Confirmed"');$q->execute([$id]);if((int)$q->fetchColumn()>0)throw new RuntimeException('This seat has a confirmed booking and cannot be moved or renumbered.');$q=$pdo->prepare('UPDATE seats SET bogie_id=?,seat_number=? WHERE seat_id=?');$q->execute([$bogie,$seat,$id]);}else{$pdo->prepare('INSERT INTO seats(bogie_id,seat_number) VALUES(?,?)')->execute([$bogie,$seat]);}}
   flash('Changes saved.');
  }
 }catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();flash($exception instanceof RuntimeException?$exception->getMessage():'Could not save this item. Check that names, codes, and allocations are unique.');}
 go('admin/manage.php',['type'=>$type]);
}
$id=(int)($_GET['id']??0);$item=null;if($id){$sql=['stations'=>'SELECT * FROM stations WHERE station_id=?','routes'=>'SELECT * FROM routes WHERE route_id=?','trains'=>'SELECT * FROM trains WHERE train_id=?','schedules'=>'SELECT * FROM schedules WHERE schedule_id=?','bogies'=>'SELECT * FROM bogies WHERE bogie_id=?','seats'=>'SELECT * FROM seats WHERE seat_id=?'];$q=$pdo->prepare($sql[$type]);$q->execute([$id]);$item=$q->fetch();}
$stations=$pdo->query('SELECT station_id,station_name FROM stations ORDER BY station_order,station_name')->fetchAll();$trains=$pdo->query('SELECT train_id,train_name,train_code FROM trains ORDER BY train_name')->fetchAll();$routes=$pdo->query('SELECT route_id,route_name FROM routes ORDER BY route_name')->fetchAll();$bogies=$pdo->query('SELECT b.bogie_id,b.bogie_code,b.category,b.gender,t.train_name FROM bogies b JOIN trains t ON t.train_id=b.train_id ORDER BY t.train_name,b.bogie_code')->fetchAll();
$queries=['stations'=>'SELECT * FROM stations ORDER BY station_order,station_name','routes'=>'SELECT r.*,o.station_name origin,d.station_name destination FROM routes r JOIN stations o ON o.station_id=r.origin_station_id JOIN stations d ON d.station_id=r.destination_station_id ORDER BY route_name','trains'=>'SELECT * FROM trains ORDER BY train_name','schedules'=>'SELECT sc.*,t.train_name,t.train_code,r.route_name FROM schedules sc JOIN trains t ON t.train_id=sc.train_id JOIN routes r ON r.route_id=sc.route_id ORDER BY sc.departure_time','bogies'=>'SELECT b.*,t.train_name,(SELECT COUNT(*) FROM seats s WHERE s.bogie_id=b.bogie_id AND s.is_active=1) seat_count FROM bogies b JOIN trains t ON t.train_id=b.train_id ORDER BY t.train_name,b.bogie_code','seats'=>'SELECT s.*,b.bogie_code,b.category,b.gender,t.train_name FROM seats s JOIN bogies b ON b.bogie_id=s.bogie_id JOIN trains t ON t.train_id=b.train_id ORDER BY t.train_name,b.bogie_code,s.seat_number'];$rows=$pdo->query($queries[$type])->fetchAll();
$pageTitle='Manage '.$type;require __DIR__.'/../includes/header.php';?>
<section class="content"><span class="eyebrow">SYSTEM DATA</span><h1>Manage railway data</h1><div class="admin-tabs"><?php foreach($types as $tab):?><a class="<?=($type===$tab?'selected':'')?>" href="<?=e(app_url('admin/manage.php',['type'=>$tab]))?>"><?=e(ucfirst($tab))?></a><?php endforeach?></div>
