<?php elseif($type==='trains'):?><label>Train name<input name="train_name" maxlength="120" required value="<?=e($item['train_name']??'')?>"></label><label>Train code<input name="train_code" maxlength="30" required value="<?=e($item['train_code']??'')?>"></label>
<?php elseif($type==='schedules'):?><label>Train<select name="train_id" required><?php foreach($trains as $t):?><option value="<?=e($t['train_id'])?>" <?=((int)($item['train_id']??0)===(int)$t['train_id']?'selected':'')?>><?=e($t['train_code'].' · '.$t['train_name'])?></option><?php endforeach?></select></label><label>Route<select name="route_id" required><?php foreach($routes as $r):?><option value="<?=e($r['route_id'])?>" <?=((int)($item['route_id']??0)===(int)$r['route_id']?'selected':'')?>><?=e($r['route_name'])?></option><?php endforeach?></select></label><label>Departure<input type="time" name="departure_time" required value="<?=e(isset($item['departure_time'])?substr($item['departure_time'],0,5):'')?>"></label><label>Arrival<input type="time" name="arrival_time" required value="<?=e(isset($item['arrival_time'])?substr($item['arrival_time'],0,5):'')?>"></label><label>Service days<input name="service_days" maxlength="80" required placeholder="Daily or Mon,Tue,Wed" value="<?=e($item['service_days']??'Daily')?>"></label><label>Valid from (optional)<input type="date" name="valid_from" value="<?=e($item['valid_from']??'')?>"></label><label>Valid until (optional)<input type="date" name="valid_until" value="<?=e($item['valid_until']??'')?>"></label>
<?php elseif($type==='bogies'):?><label>Train<select name="train_id" required><?php foreach($trains as $t):?><option value="<?=e($t['train_id'])?>" <?=((int)($item['train_id']??0)===(int)$t['train_id']?'selected':'')?>><?=e($t['train_name'])?></option><?php endforeach?></select></label><label>Bogie code<input name="bogie_code" maxlength="10" required value="<?=e($item['bogie_code']??'')?>"></label><label>Category<select name="category"><?php foreach(['Student','Teacher','Staff'] as $v):?><option <?=($item['category']??'')===$v?'selected':''?>><?=e($v)?></option><?php endforeach?></select></label><label>Gender<select name="gender"><?php foreach(['Male','Female'] as $v):?><option <?=($item['gender']??'')===$v?'selected':''?>><?=e($v)?></option><?php endforeach?></select></label>
<?php else: ?><label>Train bogie<select name="bogie_id" required><?php foreach($bogies as $b):?><option value="<?=e($b['bogie_id'])?>" <?=((int)($item['bogie_id']??0)===(int)$b['bogie_id']?'selected':'')?>><?=e($b['train_name'].' · '.$b['bogie_code'].' '.$b['category'].'/'.$b['gender'])?></option><?php endforeach?></select></label><label>Seat number<input name="seat_number" maxlength="10" required placeholder="S01" value="<?=e($item['seat_number']??'')?>"></label><?php endif?><button class="button"><?=$item?'Save changes':'Add item'?></button><?php if($item):?><a href="<?=e(app_url('admin/manage.php',['type'=>$type]))?>">Cancel edit</a><?php endif?></form>
<h2>Current <?=e($type)?></h2><div class="list"><?php foreach($rows as $row):$rowId=(int)($row['station_id']??$row['route_id']??$row['train_id']??$row['schedule_id']??$row['bogie_id']??$row['seat_id']);$label=match($type){'stations'=>$row['station_name'].' · '.$row['station_code'],'routes'=>$row['route_name'].' · '.$row['origin'].' → '.$row['destination'],'trains'=>$row['train_name'].' · '.$row['train_code'],'schedules'=>$row['train_name'].' · '.$row['route_name'].' · '.substr($row['departure_time'],0,5).'–'.substr($row['arrival_time'],0,5),'bogies'=>$row['train_name'].' · '.$row['bogie_code'].' '.$row['category'].'/'.$row['gender'].' · '.$row['seat_count'].' seats','seats'=>$row['train_name'].' · '.$row['bogie_code'].' · '.$row['seat_number'].' '.$row['category'].'/'.$row['gender']};?><article><div><h3><?=e($label)?></h3><p><?=$row['is_active']?'Active':'Inactive'?></p></div><div class="row-actions"><a class="button pale" href="<?=e(app_url('admin/manage.php',['type'=>$type,'id'=>$rowId]))?>">Edit</a><?php if($row['is_active']):?><form method="post"><?php csrf_input();?><input type="hidden" name="action" value="deactivate"><input type="hidden" name="type" value="<?=e($type)?>"><input type="hidden" name="id" value="<?=$rowId?>"><button class="button pale">Deactivate</button></form><?php endif?></div></article><?php endforeach?><?php if(!$rows):?><article>No records yet.</article><?php endif?></div></section>
